/**
 * The automatic first open of the chat identity, as one flow in the SDK (the rule; interface r2.5.20 names are provisional:
 * chatInit and the status values follow the temporary plan until the fifth interface version). The page calls runFirstOpen and shows the
 * status; the page never receives a private key.
 *
 * One flow, one lock per wallet (R80 M1): decision → generate → save (pending, its own store) → re-read the pending copy from storage →
 * re-read the chain → register (one send; 4xx is a permanent refusal, 5xx and network retry with the backoff) → clear the pending copy.
 * A busy lock means another tab runs the flow: it is not a failure.
 */
import { generateKey, readKey } from 'openpgp'

export type ChatInitStatus = 'ready' | 'pending_confirm' | 'unknown' | 'restore_failed' | 'registering' | 'error'

export type ChainPgpRead = 'record' | 'absent' | 'unknown'
export type ChainBackupRead = 'present' | 'absent' | 'unknown'
export type RestoreKind = 'ok' | 'new_account' | 'failure' | 'read_error'
export type FirstOpenDecision = 'use_record' | 'wait_unknown' | 'keep_protection' | 'resume_pending' | 'generate_and_register'
export type RegisterClass = 'registered' | 'refused' | 'retry'

export type PendingKey = { keyID: string; privateKey: string; publicKey: string }

export type FirstOpenInputs = {
	restore: RestoreKind
	chain: ChainPgpRead
	chainBackup: ChainBackupRead
	localOldIdentity: boolean
	localPendingOwn: boolean
}

const PUB_BEGIN = '-----BEGIN PGP PUBLIC KEY BLOCK-----'
const PUB_END = '-----END PGP PUBLIC KEY BLOCK-----'

/** A structural check of an armored public key: a record that is not an armor is not a record (R80 M4). */
export function wellFormedPublicArmor(armor: string): boolean {
	const b = armor.indexOf(PUB_BEGIN)
	const e = armor.indexOf(PUB_END)
	return b >= 0 && e > b
}

/** The AddressPGP answer in three states: a definite empty answer is absent; a readable record is record; anything else is unknown. */
export function chainReadFromLookup(lookup: { status: 'ok' | 'no_record' | 'network_error'; publicArmored?: string; routersArmoreds?: string }): ChainPgpRead {
	if (lookup.status === 'no_record') return 'absent'
	if (lookup.status !== 'ok') return 'unknown'
	return wellFormedPublicArmor(lookup.publicArmored ?? '') && wellFormedPublicArmor(lookup.routersArmoreds ?? '') ? 'record' : 'unknown'
}

/** The encrypted backup in three states: missing is absent; ok or undecryptable is present; an error is unknown (never absent). */
export function chainBackupFromRead(blob: string): ChainBackupRead {
	if (blob === 'missing') return 'absent'
	if (blob === 'ok' || blob === 'undecryptable') return 'present'
	return 'unknown'
}

/** The restore judgement, as the page's classifyOwnPgp gives it for a first open (no local key). Same rules, kept in step by tests. */
export function restoreKindFromRead(read: { status: 'empty' } | { status: 'ok'; privateBlob: string } | { status: 'error' }): RestoreKind {
	if (read.status === 'error') return 'read_error'
	if (read.status === 'empty') return 'new_account'
	if (read.privateBlob === 'missing' || read.privateBlob === 'undecryptable') return 'failure'
	if (read.privateBlob === 'error') return 'read_error'
	return 'ok'
}

/** The local identity, from two separate places: the chat key (complete, and whether the flow made it) and the pending copy. */
export function classifyLocalIdentity(input: { chatKeyComplete: boolean; chatKeyAutoGenerated: boolean; pendingKeyPresent: boolean }): {
	localOldIdentity: boolean
	localPendingOwn: boolean
} {
	return {
		localOldIdentity: input.chatKeyComplete && !input.chatKeyAutoGenerated && !input.pendingKeyPresent,
		localPendingOwn: input.pendingKeyPresent || (input.chatKeyComplete && input.chatKeyAutoGenerated),
	}
}

/** The decision table (the first matching row wins). */
export function firstOpenDecision(i: FirstOpenInputs): FirstOpenDecision {
	if (i.restore === 'failure') return 'keep_protection'
	if (i.restore === 'read_error') return 'wait_unknown'
	if (i.restore === 'ok') return i.chain === 'unknown' ? 'wait_unknown' : 'use_record'
	if (i.chain === 'unknown') return 'wait_unknown'
	if (i.chain === 'record') return 'use_record'
	if (i.chainBackup === 'unknown') return 'wait_unknown'
	if (i.chainBackup === 'present' || i.localOldIdentity) return 'keep_protection'
	if (i.localPendingOwn) return 'resume_pending'
	return 'generate_and_register'
}

/**
 * The read-only candidate test for the automatic claim gate: true only when the flow would generate or continue a key, i.e.
 * the first identity is confirmed. Any other state (a record, unknown, a restore protection) is not a candidate.
 */
export function isFirstOpenCandidate(i: FirstOpenInputs): boolean {
	const d = firstOpenDecision(i)
	return d === 'generate_and_register' || d === 'resume_pending'
}

/** The class of a registration outcome (the POST status, read in the SDK): 2xx registered; 4xx refused; 5xx and no answer retry. */
export function classifyRegisterStatus(status: number | null): RegisterClass {
	if (status !== null && status >= 200 && status < 300) return 'registered'
	if (status !== null && status >= 400 && status < 500) return 'refused'
	return 'retry'
}

/** A chat PGP key pair and its key ID, generated in the SDK (the same parameters as the page's generator, passphrase empty). */
export async function generatePgpKeyPair(walletAddr: string): Promise<PendingKey> {
	const { privateKey, publicKey } = await generateKey({
		type: 'ecc',
		curve: 'curve25519',
		passphrase: '',
		userIDs: [{ name: walletAddr }],
		format: 'armored',
	} as never)
	const keyObj = await readKey({ armoredKey: publicKey as unknown as string })
	const keyID = keyObj.getKeyIDs()[1].toHex().toUpperCase()
	return { keyID, privateKey: privateKey as unknown as string, publicKey: publicKey as unknown as string }
}

export type LockRequest = (name: string, options: { ifAvailable: boolean }, cb: (lock: unknown) => Promise<unknown>) => Promise<unknown>
export type LockManagerLike = { request: LockRequest }
const inProcess = new Set<string>()

/** Runs `fn` only when no other first open of this wallet is in flight, in any tab (Web Locks) or in this process. Busy returns 'busy'. */
export function withFirstOpenLock<T>(eoa: string, fn: () => Promise<T>, locks?: LockManagerLike): Promise<T | 'busy'> {
	const name = `beamio-first-open:${eoa.toLowerCase()}`
	const manager = locks ?? (globalThis as { navigator?: { locks?: LockManagerLike } }).navigator?.locks
	if (manager && typeof manager.request === 'function') {
		return manager.request(name, { ifAvailable: true }, async (lock) => (lock ? fn() : 'busy')) as Promise<T | 'busy'>
	}
	if (inProcess.has(name)) return Promise.resolve('busy')
	inProcess.add(name)
	return fn().finally(() => inProcess.delete(name))
}

export type FirstOpenDeps = {
	/** The inputs read from the chain and from this device, now (the pending copy is read from its own store). */
	readInputs: () => Promise<FirstOpenInputs>
	/** The chain answer re-read under the lock, just before the send. */
	readChain: () => Promise<ChainPgpRead>
	/** The pending copy from its own store, read fresh (never a cached copy). */
	loadPending: () => Promise<PendingKey | null>
	/** Saves a pending copy before anything is sent. Resolves true only when it is saved. */
	savePending: (key: PendingKey) => Promise<boolean>
	/** Clears the pending copy after the chain holds the key. */
	clearPending: () => Promise<boolean>
	/** Generates a key pair and its key ID (the same parameters as the page's generator). */
	generateKeys: () => Promise<PendingKey>
	/** One registration send, classified by its HTTP status. */
	register: (key: PendingKey) => Promise<RegisterClass>
	/** True when this wallet was refused permanently on this device (4xx): nothing is sent again. */
	refusedBefore: () => boolean
	markRefused: () => void
	/** Records the backoff after a retry-class failure. */
	recordFailure: () => void
	/** Milliseconds left in the backoff (0: may send). */
	backoffMs: () => number
}

export type ChatInitResult = { status: ChatInitStatus; keyID?: string }

/**
 * The whole flow under one lock (R80 M1). The status is the only output for the page: no key crosses this boundary.
 */
/**
 * The flow without the lock: the caller holds the wallet's lock (the worker command takes it, so it can read and write its persisted hold too).
 */
export async function runFirstOpenLocked(_eoa: string, deps: FirstOpenDeps): Promise<ChatInitResult> {
	if (deps.refusedBefore()) return { status: 'error' }
	const inputs = await deps.readInputs()
	const decision = firstOpenDecision(inputs)
	if (decision === 'use_record') {
		// the chain holds the record: a pending copy kept for a delayed read is no longer needed (R92)
		await deps.clearPending()
	return { status: 'ready' }
	}
	if (decision === 'wait_unknown') return { status: 'unknown' }
	if (decision === 'keep_protection') return { status: inputs.restore === 'failure' || inputs.chainBackup === 'present' ? 'restore_failed' : 'ready' }
	if (deps.backoffMs() > 0) return { status: 'pending_confirm' }
	if (decision === 'generate_and_register') {
		const keys = await deps.generateKeys()
		if (!(await deps.savePending(keys))) return { status: 'error' }
	}
	// the pending copy is read from its own store under the lock, so a second tab cannot work from an older copy
	const pending = await deps.loadPending()
	if (!pending) return { status: 'error' }
	const again = await deps.readChain()
	if (again === 'record') {
		await deps.clearPending()
	return { status: 'ready' }
	}
	if (again === 'unknown') return { status: 'unknown' }
	const cls = await deps.register(pending)
	if (cls === 'registered') {
		// R92: the pending copy stays until the chain shows the record (relay writes can be delayed). A later run reads the record
		// (use_record clears it) or resumes this same key; it never generates a second key while the copy is kept.
	return { status: 'registering', keyID: pending.keyID }
	}
	if (cls === 'refused') {
		deps.markRefused()
	return { status: 'error' }
	}
	deps.recordFailure()
	return { status: 'pending_confirm', keyID: pending.keyID }

}

export async function runFirstOpen(eoa: string, deps: FirstOpenDeps, locks?: LockManagerLike): Promise<ChatInitResult> {
	const r = await withFirstOpenLock<ChatInitResult>(eoa, () => runFirstOpenLocked(eoa, deps), locks)
	if (r === 'busy') return { status: 'registering' }
	return r
}
